package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	_ "net/http/pprof"
	"os"
	"os/exec"
	"strings"

	"github.com/mattn/go-shellwords"
	"github.com/prometheus/client_golang/prometheus/promhttp"

	"github.com/benbjohnson/litestream"
	"github.com/benbjohnson/litestream/abs"
	"github.com/benbjohnson/litestream/file"
	"github.com/benbjohnson/litestream/gs"
	"github.com/benbjohnson/litestream/internal"
	"github.com/benbjohnson/litestream/nats"
	"github.com/benbjohnson/litestream/oss"
	"github.com/benbjohnson/litestream/s3"
	"github.com/benbjohnson/litestream/sftp"
)

// ReplicateCommand represents a command that continuously replicates SQLite databases.
type ReplicateCommand struct {
	cmd    *exec.Cmd  // subcommand
	execCh chan error // subcommand error channel

	// One-shot replication flags
	once             bool // replicate once and exit
	forceSnapshot    bool // force snapshot to all replicas
	enforceRetention bool // enforce retention of old snapshots

	Config Config

	// MCP server
	MCP *MCPServer

	// Server for IPC control commands.
	Server *litestream.Server

	// Manages the set of databases & compaction levels.
	Store *litestream.Store

	// Directory monitors for dynamic database discovery.
	directoryMonitors []*DirectoryMonitor

	// Done channel for interrupt handling during shutdown. When closed,
	// the shutdown sync retry loop exits and any in-flight sync is cancelled.
	done <-chan struct{}
}

func NewReplicateCommand() *ReplicateCommand {
	return &ReplicateCommand{
		execCh: make(chan error),
	}
}

// ParseFlags parses the CLI flags and loads the configuration file.
func (c *ReplicateCommand) ParseFlags(_ context.Context, args []string) (err error) {
	fs := flag.NewFlagSet("litestream-replicate", flag.ContinueOnError)
	execFlag := fs.String("exec", "", "execute subcommand")
	logLevelFlag := fs.String("log-level", "", "log level (trace, debug, info, warn, error)")
	restoreIfDBNotExists := fs.Bool("restore-if-db-not-exists", false, "restore from replica if database doesn't exist")
	onceFlag := fs.Bool("once", false, "replicate once and exit")
	forceSnapshotFlag := fs.Bool("force-snapshot", false, "force snapshot when replicating once")
	enforceRetentionFlag := fs.Bool("enforce-retention", false, "enforce retention of old snapshots when replicating once")
	configPath, noExpandEnv := registerConfigFlag(fs)
	fs.Usage = c.Usage
	if err := fs.Parse(args); err != nil {
		return err
	}

	// Load configuration or use CLI args to build db/replica.
	switch fs.NArg() {
	case 0:
		// No arguments provided, use config file
		if *configPath == "" {
			*configPath = DefaultConfigPath()
		}
		if c.Config, err = ReadConfigFile(*configPath, !*noExpandEnv); err != nil {
			return err
		}
		// Override log level if CLI flag provided (takes precedence over env var)
		if *logLevelFlag != "" {
			c.Config.Logging.Level = *logLevelFlag
			// Set env var so initLog sees CLI flag as highest priority
			os.Setenv("LOG_LEVEL", *logLevelFlag)
			logOutput := os.Stdout
			if c.Config.Logging.Stderr {
				logOutput = os.Stderr
			}
			internal.InitLog(logOutput, c.Config.Logging.Level, c.Config.Logging.Type, c.Config.Logging.Source)
		}

	case 1:
		// Only database path provided, missing replica URL
		return fmt.Errorf("must specify at least one replica URL for %s", fs.Arg(0))

	default:
		// Database path and replica URLs provided via CLI
		if *configPath != "" {
			return fmt.Errorf("cannot specify a replica URL and the -config flag")
		}

		// Initialize config with defaults when using command-line arguments
		c.Config = DefaultConfig()
		logLevel := "INFO"
		if *logLevelFlag != "" {
			logLevel = *logLevelFlag
			// Set env var so initLog sees CLI flag as highest priority
			os.Setenv("LOG_LEVEL", *logLevelFlag)
		}
		c.Config.Logging.Level = logLevel
		internal.InitLog(os.Stdout, logLevel, "text", false)

		dbConfig := &DBConfig{
			Path:                 fs.Arg(0),
			RestoreIfDBNotExists: *restoreIfDBNotExists,
		}
		for _, u := range fs.Args()[1:] {
			// Check if this looks like a flag that was placed after positional arguments
			if strings.HasPrefix(u, "-") {
				return fmt.Errorf("flag %q must be positioned before DB_PATH and REPLICA_URL arguments", u)
			}
			syncInterval := litestream.DefaultSyncInterval
			dbConfig.Replicas = append(dbConfig.Replicas, &ReplicaConfig{
				URL: u,
				ReplicaSettings: ReplicaSettings{
					SyncInterval: &syncInterval,
				},
			})
		}
		c.Config.DBs = []*DBConfig{dbConfig}
	}

	c.Config.ConfigPath = *configPath

	// Override config exec command, if specified.
	if *execFlag != "" {
		c.Config.Exec = *execFlag
	}

	// Apply restore-if-db-not-exists flag to all databases if specified.
	// This allows the CLI flag to work with config files.
	if *restoreIfDBNotExists {
		for _, dbConfig := range c.Config.DBs {
			dbConfig.RestoreIfDBNotExists = true
		}
	}

	// Set one-shot replication flags and validate their usage.
	c.once = *onceFlag
	c.forceSnapshot = *forceSnapshotFlag
	c.enforceRetention = *enforceRetentionFlag

	// Validate flag combinations.
	if c.once && c.Config.Exec != "" {
		return fmt.Errorf("cannot specify -once flag with -exec")
	}
	if c.forceSnapshot && !c.once {
		return fmt.Errorf("cannot specify -force-snapshot flag without -once")
	}
	if c.enforceRetention && !c.once {
		return fmt.Errorf("cannot specify -enforce-retention flag without -once")
	}

	return nil
}

// Run loads all databases specified in the configuration.
func (c *ReplicateCommand) Run(ctx context.Context) (err error) {
	// Display version information.
	slog.Info("litestream", "version", Version, "level", c.Config.Logging.Level)

	// Start MCP server if enabled
	if c.Config.MCPAddr != "" {
		c.MCP, err = NewMCP(ctx, c.Config.ConfigPath)
		if err != nil {
			return err
		}
		go c.MCP.Start(c.Config.MCPAddr)
	}

	// Setup databases.
	if len(c.Config.DBs) == 0 {
		slog.Error("no databases specified in configuration")
	}

	// Attempt restore for databases that need it (before creating DB objects)
	for _, dbConfig := range c.Config.DBs {
		if dbConfig.RestoreIfDBNotExists && dbConfig.Path != "" {
			if err := c.restoreIfNeeded(ctx, dbConfig); err != nil {
				return err
			}
		}
	}

	var dbs []*litestream.DB
	var watchables []struct {
		config *DBConfig
		dbs    []*litestream.DB
	}
	for _, dbConfig := range c.Config.DBs {
		// Handle directory configuration
		if dbConfig.Dir != "" {
			dirDbs, err := NewDBsFromDirectoryConfig(dbConfig)
			if err != nil {
				return err
			}
			dbs = append(dbs, dirDbs...)
			slog.Info("found databases in directory", "dir", dbConfig.Dir, "count", len(dirDbs), "watch", dbConfig.Watch)
			if dbConfig.Watch {
				watchables = append(watchables, struct {
					config *DBConfig
					dbs    []*litestream.DB
				}{config: dbConfig, dbs: dirDbs})
			}
		} else {
			// Handle single database configuration
			db, err := NewDBFromConfig(dbConfig)
			if err != nil {
				return err
			}
			dbs = append(dbs, db)
		}
	}

	levels := c.Config.CompactionLevels()
	c.Store = litestream.NewStore(dbs, levels)

	// Only override default snapshot interval if explicitly set in config
	if c.Config.Snapshot.Interval != nil {
		c.Store.SnapshotInterval = *c.Config.Snapshot.Interval
	}
	// Only override default snapshot retention if explicitly set in config
	if c.Config.Snapshot.Retention != nil {
		c.Store.SnapshotRetention = *c.Config.Snapshot.Retention
	}
	if c.Config.L0Retention != nil {
		c.Store.SetL0Retention(*c.Config.L0Retention)
	}
	if c.Config.L0RetentionCheckInterval != nil {
		c.Store.L0RetentionCheckInterval = *c.Config.L0RetentionCheckInterval
	}
	if c.Config.ShutdownSyncTimeout != nil {
		c.Store.SetShutdownSyncTimeout(*c.Config.ShutdownSyncTimeout)
	}
	if c.Config.ShutdownSyncInterval != nil {
		c.Store.SetShutdownSyncInterval(*c.Config.ShutdownSyncInterval)
	}
	if c.Config.VerifyCompaction {
		c.Store.SetVerifyCompaction(true)
	}
	if c.Config.Retention.Enabled != nil && !*c.Config.Retention.Enabled {
		c.Store.SetRetentionEnabled(false)
	}
	if c.Config.Validation.Interval != nil {
		c.Store.ValidationInterval = *c.Config.Validation.Interval
	}
	if c.done != nil {
		c.Store.SetDone(c.done)
	}
	if c.Config.HeartbeatURL != "" {
		interval := litestream.DefaultHeartbeatInterval
		if c.Config.HeartbeatInterval != nil {
			interval = *c.Config.HeartbeatInterval
		}
		c.Store.Heartbeat = litestream.NewHeartbeatClient(c.Config.HeartbeatURL, interval)
	}

	// Disable all background monitors when running once.
	// This must be done after config settings are applied.
	if c.once {
		c.Store.CompactionMonitorEnabled = false
		c.Store.L0RetentionCheckInterval = 0
		for _, db := range dbs {
			db.MonitorInterval = 0
			if db.Replica != nil {
				db.Replica.MonitorEnabled = false
			}
		}
	}

	if err := c.Store.Open(ctx); err != nil {
		return fmt.Errorf("cannot open store: %w", err)
	}

	if !c.Store.RetentionEnabled {
		slog.Warn("retention disabled; cloud provider lifecycle policies must handle retention",
			"hint", "idle databases that stop receiving writes will not generate new snapshots and may lose backup coverage if cloud retention expires")
	}

	// Start control server if socket is enabled
	if c.Config.Socket.Enabled {
		c.Server = litestream.NewServer(c.Store)
		c.Server.SocketPath = c.Config.Socket.Path
		c.Server.SocketPerms = c.Config.Socket.Permissions
		c.Server.PathExpander = expand
		c.Server.Version = Version
		if err := c.Server.Start(); err != nil {
			slog.Warn("failed to start control server", "error", err)
		}
	}

	for _, entry := range watchables {
		monitor, err := NewDirectoryMonitor(ctx, c.Store, entry.config, entry.dbs)
		if err != nil {
			for _, m := range c.directoryMonitors {
				m.Close()
			}
			if closeErr := c.Store.Close(ctx); closeErr != nil {
				slog.Error("failed to close store after monitor failure", "error", closeErr)
			}
			return fmt.Errorf("start directory monitor for %s: %w", entry.config.Dir, err)
		}
		c.directoryMonitors = append(c.directoryMonitors, monitor)
	}

	// Notify user that initialization is done.
	for _, db := range c.Store.DBs() {
		r := db.Replica
		slog.Info("initialized db", "path", db.Path())
		slogWith := slog.With("type", r.Client.Type(), "sync-interval", r.SyncInterval)
		switch client := r.Client.(type) {
		case *file.ReplicaClient:
			slogWith.Info("replicating to", "path", client.Path())
		case *s3.ReplicaClient:
			slogWith.Info("replicating to", "bucket", client.Bucket, "path", client.Path, "region", client.Region, "endpoint", client.Endpoint)
		case *gs.ReplicaClient:
			slogWith.Info("replicating to", "bucket", client.Bucket, "path", client.Path)
		case *abs.ReplicaClient:
			slogWith.Info("replicating to", "bucket", client.Bucket, "path", client.Path, "endpoint", client.Endpoint)
		case *sftp.ReplicaClient:
			slogWith.Info("replicating to", "host", client.Host, "user", client.User, "path", client.Path)
		case *nats.ReplicaClient:
			slogWith.Info("replicating to", "bucket", client.BucketName, "url", client.URL)
		case *oss.ReplicaClient:
			slogWith.Info("replicating to", "bucket", client.Bucket, "path", client.Path, "region", client.Region)
		default:
			slogWith.Info("replicating to")
		}
	}

	// Serve metrics over HTTP if enabled.
	if c.Config.Addr != "" {
		hostport := c.Config.Addr
		if host, port, _ := net.SplitHostPort(c.Config.Addr); port == "" {
			return fmt.Errorf("must specify port for bind address: %q", c.Config.Addr)
		} else if host == "" {
			hostport = net.JoinHostPort("localhost", port)
		}

		slog.Info("serving metrics on", "url", fmt.Sprintf("http://%s/metrics", hostport))
		go func() {
			http.Handle("/metrics", promhttp.Handler())
			if err := http.ListenAndServe(c.Config.Addr, nil); err != nil {
				slog.Error("cannot start metrics server", "error", err)
			}
		}()
	}

	// Parse exec commands args & start subprocess.
	if c.Config.Exec != "" {
		execArgs, err := shellwords.Parse(c.Config.Exec)
		if err != nil {
			return fmt.Errorf("cannot parse exec command: %w", err)
		}

		c.cmd = exec.CommandContext(ctx, execArgs[0], execArgs[1:]...)
		c.cmd.Env = os.Environ()
		c.cmd.Stdout = os.Stdout
		c.cmd.Stderr = os.Stderr
		if err := c.cmd.Start(); err != nil {
			return fmt.Errorf("cannot start exec command: %w", err)
		}
		go func() { c.execCh <- c.cmd.Wait() }()
	} else if c.once {
		// Run one-shot replication in a goroutine so the caller can wait on execCh.
		go c.runOnce(ctx)
	}

	return nil
}

// runOnce performs one-shot replication for all databases.
// It syncs all databases, optionally takes snapshots, and enforces retention.
func (c *ReplicateCommand) runOnce(ctx context.Context) {
	var err error
	defer func() { c.execCh <- err }()

	for _, db := range c.Store.DBs() {
		slog.Info("syncing database", "path", db.Path())

		// Sync the database to process any pending WAL changes.
		if err = db.Sync(ctx); err != nil {
			err = fmt.Errorf("sync database %s: %w", db.Path(), err)
			return
		}

		// Sync the replica to upload any pending LTX files.
		if err = db.Replica.Sync(ctx); err != nil {
			err = fmt.Errorf("sync replica for %s: %w", db.Path(), err)
			return
		}

		// Force a snapshot if requested.
		if c.forceSnapshot {
			slog.Info("taking snapshot", "path", db.Path())
			if _, err = db.Snapshot(ctx); err != nil {
				err = fmt.Errorf("snapshot %s: %w", db.Path(), err)
				return
			}
		}

		// Enforce retention if requested.
		if c.enforceRetention {
			slog.Info("enforcing retention", "path", db.Path())
			if err = c.Store.EnforceSnapshotRetention(ctx, db); err != nil {
				err = fmt.Errorf("enforce retention for %s: %w", db.Path(), err)
				return
			}
		}
	}

	slog.Info("one-shot replication complete")
}

// Close closes all open databases.
func (c *ReplicateCommand) Close(ctx context.Context) error {
	for _, monitor := range c.directoryMonitors {
		monitor.Close()
	}
	c.directoryMonitors = nil

	if c.Server != nil {
		if err := c.Server.Close(); err != nil {
			slog.Error("error closing control server", "error", err)
		}
	}
	if c.Store != nil {
		if err := c.Store.Close(ctx); err != nil {
			if errors.Is(err, litestream.ErrShutdownInterrupted) {
				slog.Warn("shutdown sync skipped by user interrupt", "error", err)
			} else {
				slog.Error("failed to close database", "error", err)
			}
		}
	}
	if c.Config.MCPAddr != "" && c.MCP != nil {
		if err := c.MCP.Close(); err != nil {
			slog.Error("error closing MCP server", "error", err)
		}
	}
	return nil
}

// SetDone sets the done channel used for interrupt handling during shutdown.
// When the channel is closed, the shutdown sync retry loop exits.
func (c *ReplicateCommand) SetDone(done <-chan struct{}) {
	c.done = done
}

// restoreIfNeeded restores a database from its replica if the database doesn't
// exist and the RestoreIfDBNotExists option is enabled. If no backup exists
// (first start scenario), it returns nil to allow fresh replication to begin.
func (c *ReplicateCommand) restoreIfNeeded(ctx context.Context, dbConfig *DBConfig) error {
	dbPath, err := expand(dbConfig.Path)
	if err != nil {
		return err
	}

	// Skip if database already exists
	if _, err := os.Stat(dbPath); !os.IsNotExist(err) {
		slog.Info("database exists, skipping restore", "path", dbPath)
		return nil
	}

	// Get replica config (handles both Replica and Replicas fields)
	var rc *ReplicaConfig
	if dbConfig.Replica != nil {
		rc = dbConfig.Replica
	} else if len(dbConfig.Replicas) > 0 {
		rc = dbConfig.Replicas[0]
	} else {
		return fmt.Errorf("no replica configured for database: %s", dbPath)
	}

	// Create replica from config (nil db since we're just restoring)
	r, err := NewReplicaFromConfig(rc, nil)
	if err != nil {
		return fmt.Errorf("cannot create replica for restore: %w", err)
	}

	// Attempt restore
	opt := litestream.NewRestoreOptions()
	opt.OutputPath = dbPath

	slog.Info("attempting restore before replication", "path", dbPath)
	if err := r.Restore(ctx, opt); errors.Is(err, litestream.ErrTxNotAvailable) {
		// No backup exists yet (first start) - this is OK
		slog.Info("no backup found, starting fresh", "path", dbPath)
		return nil
	} else if err != nil {
		return fmt.Errorf("restore failed: %w", err)
	}

	slog.Info("restore completed", "path", dbPath)
	return nil
}

// Usage prints the help screen to STDOUT.
func (c *ReplicateCommand) Usage() {
	fmt.Printf(`
The replicate command starts a server to monitor & replicate databases.
You can specify your database & replicas in a configuration file or you can
replicate a single database file by specifying its path and its replicas in the
command line arguments.

Usage:

	litestream replicate [arguments]

	litestream replicate [arguments] DB_PATH REPLICA_URL

Arguments:

	-config PATH
	    Specifies the configuration file.
	    Defaults to %s

	-exec CMD
	    Executes a subcommand. Litestream will exit when the child
	    process exits. Useful for simple process management.

	-once
	    Replicate once and exit. This performs a single sync of all
	    databases and their replicas, then exits. Cannot be used with -exec.

	-force-snapshot
	    Force a snapshot to be taken for all databases. Requires -once.
	    This is useful for creating a complete backup before maintenance
	    or when migrating databases between hosts.

	-enforce-retention
	    Enforce retention policies for old snapshots. Requires -once.
	    This removes snapshots that are older than the configured
	    snapshot retention period.

	-log-level LEVEL
	    Sets the log level. Overrides the config file setting.
	    Valid values: trace, debug, info, warn, error

	-no-expand-env
	    Disables environment variable expansion in configuration file.

	-restore-if-db-not-exists
	    Restores the database from the replica if it doesn't exist.
	    On first start with no backup, proceeds normally.

Runtime control commands require the daemon control socket. This includes
start, stop, sync, register, unregister, info, and list. Enable it in the config:

	socket:
	  enabled: true
	  path: /tmp/litestream.sock

`[1:], DefaultConfigPath())
}

cmd/litestream/reset.go.source:
package main

import (
	"context"
	"flag"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"

	"github.com/benbjohnson/litestream"
)

// ResetCommand is a command for resetting local Litestream state for a database.
type ResetCommand struct{}

// Run executes the command.
func (c *ResetCommand) Run(ctx context.Context, args []string) (err error) {
	fs := flag.NewFlagSet("litestream-reset", flag.ContinueOnError)
	configPath, noExpandEnv := registerConfigFlag(fs)
	dryRun := fs.Bool("dry-run", false, "print local state that would be removed without deleting")
	fs.Usage = c.Usage
	if err := fs.Parse(args); err != nil {
		return err
	}

	// Validate arguments - need exactly one database path
	if fs.NArg() == 0 {
		return &usageError{
			message: "database path required",
			hint:    "litestream reset /path/to/db",
		}
	} else if fs.NArg() > 1 {
		return fmt.Errorf("too many arguments")
	}

	dbPath := fs.Arg(0)

	// Make absolute if needed
	if !filepath.IsAbs(dbPath) {
		if dbPath, err = filepath.Abs(dbPath); err != nil {
			return err
		}
	}

	// Load configuration to find the database (if config exists)
	var dbConfig *DBConfig
	if *configPath != "" {
		config, configErr := ReadConfigFile(*configPath, !*noExpandEnv)
		if configErr != nil {
			return fmt.Errorf("cannot read config: %w", configErr)
		}

		// Find database config
		for _, dbc := range config.DBs {
			expandedPath := dbc.Path
			if !filepath.IsAbs(expandedPath) {
				expandedPath, _ = filepath.Abs(expandedPath)
			}
			if expandedPath == dbPath {
				dbConfig = dbc
				break
			}
		}
	}

	// If no config found, check if database file exists
	if _, err := os.Stat(dbPath); os.IsNotExist(err) {
		return fmt.Errorf("database does not exist: %s", dbPath)
	} else if err != nil {
		return fmt.Errorf("cannot access database: %w", err)
	}

	// Create DB instance
	var db *litestream.DB
	if dbConfig != nil {
		db, err = NewDBFromConfig(dbConfig)
		if err != nil {
			return fmt.Errorf("cannot create database from config: %w", err)
		}
	} else {
		db = litestream.NewDB(dbPath)
	}

	// Check if meta path exists
	metaPath := db.MetaPath()
	if _, err := os.Stat(metaPath); os.IsNotExist(err) {
		fmt.Printf("No local state to reset for %s\n", dbPath)
		fmt.Printf("Meta directory does not exist: %s\n", metaPath)
		return nil
	}

	if *dryRun {
		files, err := localLTXFiles(db.LTXDir())
		if err != nil {
			return fmt.Errorf("dry run failed: %w", err)
		}

		fmt.Printf("Dry run: local Litestream state would be reset for: %s\n", dbPath)
		fmt.Printf("Would remove: %s\n", db.LTXDir())
		if len(files) == 0 {
			fmt.Println("No local LTX files would be removed.")
			return nil
		}

		fmt.Println("Files that would be removed:")
		for _, file := range files {
			fmt.Printf("  %s\n", file)
		}
		fmt.Println("No files were removed.")
		return nil
	}

	// Perform the reset
	fmt.Printf("Resetting local Litestream state for: %s\n", dbPath)
	fmt.Printf("Removing: %s\n", db.LTXDir())

	if err := db.ResetLocalState(ctx); err != nil {
		return fmt.Errorf("reset failed: %w", err)
	}

	fmt.Println("Reset complete. Next replication sync will create a fresh snapshot.")
	return nil
}

func localLTXFiles(root string) ([]string, error) {
	if _, err := os.Stat(root); os.IsNotExist(err) {
		return nil, nil
	} else if err != nil {
		return nil, err
	}

	var files []string
	if err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		files = append(files, path)
		return nil
	}); err != nil {
		return nil, err
	}
	return files, nil
}

// Usage prints the help screen to STDOUT.
func (c *ResetCommand) Usage() {
	fmt.Printf(`
The reset command clears local Litestream state for a database.

This is useful for recovering from corrupted or missing LTX files. The reset
removes local LTX files from the metadata directory, forcing Litestream to
create a fresh snapshot on the next sync. The database file itself is not
modified.

Usage:

	litestream reset [arguments] <path>

Arguments:

	-config PATH
	    Specifies the configuration file.
	    Defaults to %s

	-no-expand-env
	    Disables environment variable expansion in configuration file.

	-dry-run
	    Print the local LTX files that would be removed without deleting them.

Examples:

	# Reset local state for a specific database
	litestream reset /path/to/database.db

	# Preview local files that would be removed
	litestream reset -dry-run /path/to/database.db

	# Reset using a specific configuration file
	litestream reset -config /etc/litestream.yml /path/to/database.db

`[1:],
		DefaultConfigPath(),
	)
}

cmd/litestream/restore.go.source:
package main

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"log/slog"
	"os"
	"strconv"
	"text/tabwriter"
	"time"

	"github.com/superfly/ltx"

	"github.com/benbjohnson/litestream"
	"github.com/benbjohnson/litestream/internal"
)

// RestoreCommand represents a command to restore a database from a backup.
type RestoreCommand struct{}

// Run executes the command.
func (c *RestoreCommand) Run(ctx context.Context, args []string) (err error) {
	opt := litestream.NewRestoreOptions()

	fs := flag.NewFlagSet("litestream-restore", flag.ContinueOnError)
	configPath, noExpandEnv := registerConfigFlag(fs)
	fs.StringVar(&opt.OutputPath, "o", "", "output path")
	fs.Var((*txidVar)(&opt.TXID), "txid", "transaction ID")
	fs.IntVar(&opt.Parallelism, "parallelism", opt.Parallelism, "parallelism")
	ifDBNotExists := fs.Bool("if-db-not-exists", false, "")
	ifReplicaExists := fs.Bool("if-replica-exists", false, "")
	timestampStr := fs.String("timestamp", "", "timestamp")
	dryRun := fs.Bool("dry-run", false, "print restore plan without writing")
	force := fs.Bool("force", false, "overwrite existing output database")
	jsonOutput := fs.Bool("json", false, "output raw JSON")
	fs.BoolVar(&opt.Follow, "f", false, "follow mode")
	fs.DurationVar(&opt.FollowInterval, "follow-interval", opt.FollowInterval, "polling interval for follow mode")
	integrityCheck := fs.String("integrity-check", "none", "post-restore integrity check: none, quick, or full")
	fs.Usage = c.Usage
	if err := fs.Parse(args); err != nil {
		return err
	} else if fs.NArg() == 0 || fs.Arg(0) == "" {
		return &usageError{
			message: "database path or replica URL required",
			hint:    "litestream restore -o /path/to/db s3://bucket/prefix",
		}
	} else if fs.NArg() > 1 {
		return fmt.Errorf("too many arguments")
	}

	logOutput := os.Stdout
	if *jsonOutput {
		logOutput = os.Stderr
	}
	internal.InitLog(logOutput, "INFO", "text", false)

	// When follow mode is enabled, set up signal handling so Ctrl+C stops
	// the follow loop cleanly.
	if opt.Follow {
		ch := signalChan()
		cancelCtx, cancel := context.WithCancel(ctx)
		go func() {
			select {
			case <-ch:
				cancel()
			case <-cancelCtx.Done():
			}
		}()
		ctx = cancelCtx
		defer cancel()
	}

	switch *integrityCheck {
	case "none":
		opt.IntegrityCheck = litestream.IntegrityCheckNone
	case "quick":
		opt.IntegrityCheck = litestream.IntegrityCheckQuick
	case "full":
		opt.IntegrityCheck = litestream.IntegrityCheckFull
	default:
		return fmt.Errorf("invalid -integrity-check value: %s", *integrityCheck)
	}

	// Parse timestamp, if specified.
	if *timestampStr != "" {
		if opt.Timestamp, err = time.Parse(time.RFC3339, *timestampStr); err != nil {
			return errors.New("invalid -timestamp, must specify in ISO 8601 format (e.g. 2000-01-01T00:00:00Z)")
		}
	}

	// Determine replica to restore from.
	var r *litestream.Replica
	if litestream.IsURL(fs.Arg(0)) {
		if *configPath != "" {
			return fmt.Errorf("cannot specify a replica URL and the -config flag")
		}
		if r, err = c.loadFromURL(ctx, fs.Arg(0), *ifDBNotExists, &opt); errors.Is(err, errSkipDBExists) {
			slog.Info("database already exists, skipping")
			return nil
		} else if err != nil {
			return err
		}
	} else {
		if *configPath == "" {
			*configPath = DefaultConfigPath()
		}
		if r, err = c.loadFromConfig(ctx, fs.Arg(0), *configPath, !*noExpandEnv, *ifDBNotExists, &opt); errors.Is(err, errSkipDBExists) {
			slog.Info("database already exists, skipping")
			return nil
		} else if err != nil {
			return err
		}
	}

	if *dryRun {
		plan, err := c.dryRunPlan(ctx, fs.Arg(0), r, opt)
		if errors.Is(err, litestream.ErrTxNotAvailable) {
			return fmt.Errorf("no matching backup files available")
		} else if err != nil {
			return err
		}
		if *jsonOutput {
			output, err := json.MarshalIndent(plan, "", "  ")
			if err != nil {
				return fmt.Errorf("failed to format response: %w", err)
			}
			fmt.Println(string(output))
			return nil
		}
		c.printDryRunPlan(plan)
		return nil
	}

	if !opt.Follow {
		if err := c.prepareOutputPath(opt.OutputPath, *force); err != nil {
			return err
		}
	}

	txid := c.restoreTXID(ctx, r, opt)
	start := time.Now()
	if err := r.Restore(ctx, opt); errors.Is(err, litestream.ErrTxNotAvailable) {
		if *ifReplicaExists {
			slog.Info("no matching backups found")
			return nil
		}
		return fmt.Errorf("no matching backup files available")
	} else if err != nil {
		return err
	}
	if *jsonOutput {
		output, err := json.MarshalIndent(RestoreResult{
			DBPath:         opt.OutputPath,
			Replica:        r.Client.Type(),
			TXID:           txid,
			DurationMS:     time.Since(start).Milliseconds(),
			IntegrityCheck: *integrityCheck,
		}, "", "  ")
		if err != nil {
			return fmt.Errorf("failed to format response: %w", err)
		}
		fmt.Println(string(output))
	}
	return nil
}

type RestorePlan struct {
	Source     string            `json:"source"`
	TargetPath string            `json:"target_path"`
	Replica    string            `json:"replica"`
	MinTXID    string            `json:"min_txid"`
	MaxTXID    string            `json:"max_txid"`
	Files      []RestorePlanFile `json:"files"`
}

type RestorePlanFile struct {
	Level     int    `json:"level"`
	Name      string `json:"name"`
	MinTXID   string `json:"min_txid"`
	MaxTXID   string `json:"max_txid"`
	Size      int64  `json:"size"`
	Timestamp string `json:"timestamp"`
}

type RestoreResult struct {
	DBPath         string `json:"db_path"`
	Replica        string `json:"replica"`
	TXID           string `json:"txid"`
	DurationMS     int64  `json:"duration_ms"`
	IntegrityCheck string `json:"integrity_check"`
}

func (c *RestoreCommand) dryRunPlan(ctx context.Context, source string, r *litestream.Replica, opt litestream.RestoreOptions) (RestorePlan, error) {
	if opt.Follow {
		return RestorePlan{}, fmt.Errorf("cannot use -dry-run with -f")
	}

	infos, err := litestream.CalcRestorePlan(ctx, r.Client, opt.TXID, opt.Timestamp, r.Logger())
	if err != nil {
		return RestorePlan{}, err
	}
	if len(infos) == 0 {
		return RestorePlan{}, litestream.ErrTxNotAvailable
	}

	plan := RestorePlan{
		Source:     source,
		TargetPath: opt.OutputPath,
		Replica:    r.Client.Type(),
		MinTXID:    infos[0].MinTXID.String(),
		MaxTXID:    infos[len(infos)-1].MaxTXID.String(),
		Files:      make([]RestorePlanFile, 0, len(infos)),
	}
	for _, info := range infos {
		plan.Files = append(plan.Files, RestorePlanFile{
			Level:     info.Level,
			Name:      ltx.FormatFilename(info.MinTXID, info.MaxTXID),
			MinTXID:   info.MinTXID.String(),
			MaxTXID:   info.MaxTXID.String(),
			Size:      info.Size,
			Timestamp: info.CreatedAt.Format(time.RFC3339),
		})
	}
	return plan, nil
}

func (c *RestoreCommand) printDryRunPlan(plan RestorePlan) {
	fmt.Println("Restore plan:")
	fmt.Printf("  source: %s\n", plan.Source)
	fmt.Printf("  target: %s\n", plan.TargetPath)
	fmt.Printf("  replica: %s\n", plan.Replica)
	fmt.Printf("  txid range: %s - %s\n", plan.MinTXID, plan.MaxTXID)
	fmt.Println()
	fmt.Println("Files to fetch:")

	w := tabwriter.NewWriter(os.Stdout, 0, 8, 2, ' ', 0)
	defer w.Flush()
	fmt.Fprintln(w, "level\tfile\tmin_txid\tmax_txid\tsize\ttimestamp")
	for _, file := range plan.Files {
		fmt.Fprintf(w, "%d\t%s\t%s\t%s\t%d\t%s\n",
			file.Level,
			file.Name,
			file.MinTXID,
			file.MaxTXID,
			file.Size,
			file.Timestamp,
		)
	}
}

func (c *RestoreCommand) restoreTXID(ctx context.Context, r *litestream.Replica, opt litestream.RestoreOptions) string {
	if opt.TXID != 0 {
		return opt.TXID.String()
	}
	if opt.Follow {
		return ""
	}
	infos, err := litestream.CalcRestorePlan(ctx, r.Client, opt.TXID, opt.Timestamp, r.Logger())
	if err != nil || len(infos) == 0 {
		return ""
	}
	return infos[len(infos)-1].MaxTXID.String()
}

func (c *RestoreCommand) prepareOutputPath(path string, force bool) error {
	info, err := os.Stat(path)
	if os.IsNotExist(err) {
		return nil
	} else if err != nil {
		return fmt.Errorf("cannot access output path: %w", err)
	}
	if info.IsDir() {
		return fmt.Errorf("cannot restore, output path is a directory: %s", path)
	}

	if info.Size() > 0 && !force {
		return fmt.Errorf("cannot restore, output path already exists and is not empty: %s. Use -force to overwrite", path)
	}

	for _, sidecarPath := range []string{path + "-wal", path + "-shm", path + "-journal"} {
		if _, err := os.Stat(sidecarPath); err == nil && !force {
			return fmt.Errorf("cannot restore, SQLite sidecar path already exists: %s. Use -force to overwrite", sidecarPath)
		} else if err != nil && !os.IsNotExist(err) {
			return fmt.Errorf("cannot access SQLite sidecar path: %w", err)
		}
	}

	for _, removePath := range []string{path, path + "-wal", path + "-shm", path + "-journal"} {
		if err := os.Remove(removePath); err != nil && !os.IsNotExist(err) {
			return fmt.Errorf("remove existing output path: %w", err)
		}
	}
	return nil
}

// loadFromURL creates a replica & updates the restore options from a replica URL.
func (c *RestoreCommand) loadFromURL(ctx context.Context, replicaURL string, ifDBNotExists bool, opt *litestream.RestoreOptions) (*litestream.Replica, error) {
	if opt.OutputPath == "" {
		return nil, &usageError{
			message: "-o is required when restoring from a replica URL",
			hint:    fmt.Sprintf("litestream restore -o /path/to/db %s", replicaURL),
		}
	}

	// Exit successfully if the output file already exists.
	if _, err := os.Stat(opt.OutputPath); !os.IsNotExist(err) && ifDBNotExists {
		return nil, errSkipDBExists
	}

	syncInterval := litestream.DefaultSyncInterval
	r, err := NewReplicaFromConfig(&ReplicaConfig{
		URL: replicaURL,
		ReplicaSettings: ReplicaSettings{
			SyncInterval: &syncInterval,
		},
	}, nil)
	if err != nil {
		return nil, err
	}
	_, err = r.CalcRestoreTarget(ctx, *opt)
	return r, err
}

// loadFromConfig returns a replica & updates the restore options from a DB reference.
func (c *RestoreCommand) loadFromConfig(_ context.Context, dbPath, configPath string, expandEnv, ifDBNotExists bool, opt *litestream.RestoreOptions) (*litestream.Replica, error) {
	// Load configuration.
	config, err := ReadConfigFile(configPath, expandEnv)
	if err != nil {
		return nil, err
	}

	// Lookup database from configuration file by path.
	if dbPath, err = expand(dbPath); err != nil {
		return nil, err
	}
	dbConfig := config.DBConfig(dbPath)
	if dbConfig == nil {
		return nil, fmt.Errorf("database not found in config: %s", dbPath)
	}
	db, err := NewDBFromConfig(dbConfig)
	if err != nil {
		return nil, err
	}

	// Restore into original database path if not specified.
	if opt.OutputPath == "" {
		opt.OutputPath = dbPath
	}

	// Exit successfully if the output file already exists.
	if _, err := os.Stat(opt.OutputPath); !os.IsNotExist(err) && ifDBNotExists {
		return nil, errSkipDBExists
	}

	return db.Replica, nil
}

// Usage prints the help screen to STDOUT.
func (c *RestoreCommand) Usage() {
	fmt.Printf(`
The restore command recovers a database from a previous snapshot and WAL.

Usage:

	litestream restore [arguments] DB_PATH

	litestream restore [arguments] REPLICA_URL

Arguments:

	-config PATH
	    Specifies the configuration file.
	    Defaults to %s

	-no-expand-env
	    Disables environment variable expansion in configuration file.

	-txid TXID
	    Restore up to a specific hex-encoded transaction ID (inclusive).
	    Defaults to use the highest available transaction.

	-timestamp TIMESTAMP
	    Restore to a specific point-in-time.
	    Defaults to use the latest available backup.

	-o PATH
	    Output path of the restored database.
	    Defaults to original DB path.

	-if-db-not-exists
	    Returns exit code of 0 if the database already exists.

	-if-replica-exists
	    Returns exit code of 0 if no backups found.

	-dry-run
	    Print the restore plan and exit without writing a database.

	-force
	    Overwrite an existing output database and SQLite sidecar files.

	-json
	    Output raw JSON summary on successful restore.

	-f
	    Follow mode. After restoring, continuously poll for and apply
	    new changes. Similar to tail -f. The restored database should
	    only be opened in read-only mode by consumers.
	    Cannot be used with -txid or -timestamp.

	-follow-interval DURATION
	    Polling interval for follow mode.
	    Defaults to 1s.

	-parallelism NUM
	    Determines the number of WAL files downloaded in parallel.
	    Defaults to `+strconv.Itoa(litestream.DefaultRestoreParallelism)+`.

	-integrity-check MODE
	    Run a post-restore integrity check on the database.
	    MODE is one of: none, quick, full.
	    Defaults to none.


Examples:

	# Restore latest replica for database to original location.
	$ litestream restore /path/to/db

	# Restore replica for database to a given point in time.
	$ litestream restore -timestamp 2020-01-01T00:00:00Z /path/to/db

	# Restore latest replica for database to new /tmp directory
	$ litestream restore -o /tmp/db /path/to/db

	# Restore database from S3 replica URL.
	$ litestream restore -o /tmp/db s3://mybucket/db

	# Preview restore plan without writing a database.
	$ litestream restore -dry-run -o /tmp/db s3://mybucket/db

	# Continuously restore (follow) a database from a replica.
	$ litestream restore -f -o /tmp/read-replica.db s3://mybucket/db

`[1:],
		DefaultConfigPath(),
	)
}

var errSkipDBExists = errors.New("database already exists, skipping")

cmd/litestream/start.go.source:
package main

import (
	"bytes"
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"net"
	"net/http"
	"time"

	"github.com/benbjohnson/litestream"
)

// StartCommand represents the command to start replication for a database.
type StartCommand struct{}

// Run executes the start command.
func (c *StartCommand) Run(ctx context.Context, args []string) error {
	fs := flag.NewFlagSet("litestream-start", flag.ContinueOnError)
	timeout := fs.Int("timeout", 30, "timeout in seconds")
	socketPath := fs.String("socket", "/var/run/litestream.sock", "control socket path")
	jsonOutput := fs.Bool("json", false, "output raw JSON")
	fs.Usage = c.Usage
	if err := fs.Parse(args); err != nil {
		return err
	}

	if fs.NArg() == 0 {
		return &usageError{
			message: "database path required",
			hint:    "litestream start /path/to/db",
		}
	}
	if fs.NArg() > 1 {
		return fmt.Errorf("too many arguments")
	}

	dbPath := fs.Arg(0)

	// Create HTTP client that connects via Unix socket with timeout
	clientTimeout := time.Duration(*timeout) * time.Second
	client := &http.Client{
		Timeout: clientTimeout,
		Transport: &http.Transport{
			DialContext: func(_ context.Context, _, _ string) (net.Conn, error) {
				return net.DialTimeout("unix", *socketPath, clientTimeout)
			},
		},
	}

	req := litestream.StartRequest{
		Path:    dbPath,
		Timeout: *timeout,
	}
	reqBody, err := json.Marshal(req)
	if err != nil {
		return fmt.Errorf("failed to marshal request: %w", err)
	}

	resp, err := client.Post("http://localhost/start", "application/json", bytes.NewReader(reqBody))
	if err != nil {
		return fmt.Errorf("failed to connect to control socket: %w", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return fmt.Errorf("failed to read response: %w", err)
	}

	if resp.StatusCode != http.StatusOK {
		var errResp litestream.ErrorResponse
		if err := json.Unmarshal(body, &errResp); err == nil && errResp.Error != "" {
			return fmt.Errorf("start failed: %s", errResp.Error)
		}
		return fmt.Errorf("start failed: %s", string(body))
	}

	var result litestream.StartResponse
	if err := json.Unmarshal(body, &result); err != nil {
		return fmt.Errorf("failed to parse response: %w", err)
	}

	confirmation := StartStopResult{
		Status: result.Status,
		DBPath: result.Path,
		State:  "running",
		TXID:   result.TXID,
		Socket: *socketPath,
	}
	if err := printStartStopResult(confirmation, *jsonOutput); err != nil {
		return err
	}

	return nil
}

type StartStopResult struct {
	Status string `json:"status"`
	DBPath string `json:"db_path"`
	State  string `json:"state"`
	TXID   uint64 `json:"txid"`
	Socket string `json:"socket"`
}

func printStartStopResult(result StartStopResult, jsonOutput bool) error {
	if jsonOutput {
		output, err := json.MarshalIndent(result, "", "  ")
		if err != nil {
			return fmt.Errorf("failed to format response: %w", err)
		}
		fmt.Println(string(output))
		return nil
	}

	fmt.Printf("status: %s\n", result.Status)
	fmt.Printf("db_path: %s\n", result.DBPath)
	fmt.Printf("state: %s\n", result.State)
	fmt.Printf("txid: %d\n", result.TXID)
	fmt.Printf("socket: %s\n", result.Socket)

	return nil
}

// Usage prints the help text for the start command.
func (c *StartCommand) Usage() {
	fmt.Println(`
usage: litestream start [OPTIONS] DB_PATH

Start replication for a database.

Options:
  -timeout SECONDS
      Maximum time to wait in seconds (default: 30).

  -socket PATH
      Path to control socket (default: /var/run/litestream.sock).

  -json
      Output raw JSON instead of human-readable text.

Examples:
  # Start replication for a database on the running daemon.
  $ litestream start /path/to/db

  # Start replication and emit a JSON confirmation.
  $ litestream start -json /path/to/db

  # Start replication using a non-default control socket.
  $ litestream start -socket /tmp/litestream.sock /path/to/db

  # Start replication and wait up to 10 seconds for the daemon response.
  $ litestream start -timeout 10 /path/to/db
`[1:])
}

