	credsSet := "not set"
	if os.Getenv("GOOGLE_APPLICATION_CREDENTIALS") != "" {
		credsSet = "set"
	}
	tb.Logf("  GOOGLE_APPLICATION_CREDENTIALS: %s", credsSet)
	tb.Logf("  LITESTREAM_GS_BUCKET: %s", *gsBucket)
